import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        arr = []
        for _ in range(n):
            arr.append(next(iterator))
    except StopIteration:
        return

    found = False
    for i in range(n):
        for j in range(n):
            if i != j:
                s = arr[i] + arr[j]
                if s == s[::-1]:
                    found = True
                    break
        if found:
            break

    if found:
        print(1)
    else:
        print(0)

if __name__ == "__main__":
    main()
